(()=>{const q=document.querySelector('#search'),items=[...document.querySelectorAll('.product')],count=document.querySelector('#result-count');q.addEventListener('input',()=>{const s=q.value.trim().toLocaleLowerCase('pt-BR');let n=0;items.forEach(x=>{const visible=x.dataset.name.includes(s);x.hidden=!visible;if(visible)n++});count.textContent=`${n} ${n===1?'item':'itens'}`});document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));q.value=b.dataset.category; q.dispatchEvent(new Event('input'))}));document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{const text=encodeURIComponent(`Oi, Ester! Quero saber sobre ${b.dataset.product.toLowerCase()}. Você pode me passar os modelos e valores disponíveis?`);location.href=`https://wa.me/5521992276477?text=${text}`}))})();
